import * as crypto from 'crypto';
import { MongoClient, Db, Collection } from 'mongodb';
import * as http from 'http';

interface KeyRecord {
  keyId: string;
  encryptedKey: string;
  algorithm: string;
  createdAt: Date;
  metadata: object;
}

const ALLOWED_ALGORITHMS = ['aes-256-gcm', 'aes-256-cbc', 'chacha20-poly1305'] as const;
type AllowedAlgorithm = typeof ALLOWED_ALGORITHMS[number];

function getMasterKey(): Buffer {
  const raw = process.env.MASTER_KEY;
  if (!raw) {
    throw new Error('MASTER_KEY environment variable is not set');
  }
  // Accept a hex or base64 encoded 32-byte key; fail closed otherwise.
  let key: Buffer;
  if (/^[0-9a-fA-F]{64}$/.test(raw)) {
    key = Buffer.from(raw, 'hex');
  } else {
    key = Buffer.from(raw, 'base64');
  }
  if (key.length !== 32) {
    throw new Error('MASTER_KEY must be a 32-byte key (hex or base64 encoded)');
  }
  return key;
}

class CryptoKeyStore {
  private db: Db;
  private collection: Collection<KeyRecord>;
  private shutdownInProgress = false;
  private pendingOps = new Set<Promise<any>>();

  constructor(db: Db) {
    this.db = db;
    this.collection = db.collection('crypto_keys');
  }

  private deriveQueryFilter(keyId: string, opts?: { algorithm?: string }): { keyId: string; algorithm?: string } {
    if (typeof keyId !== 'string' || keyId.length === 0 || keyId.length > 128) {
      throw new Error('Invalid keyId');
    }
    const filter: { keyId: string; algorithm?: string } = { keyId: String(keyId) };
    if (opts?.algorithm) {
      const alg = String(opts.algorithm);
      if (!ALLOWED_ALGORITHMS.includes(alg as AllowedAlgorithm)) {
        throw new Error('Invalid algorithm');
      }
      filter.algorithm = alg;
    }
    return filter;
  }

  private encrypt(rawKey: Buffer): string {
    const masterKey = getMasterKey();
    const iv = crypto.randomBytes(12);
    const cipher = crypto.createCipheriv('aes-256-gcm', masterKey, iv);
    const ciphertext = Buffer.concat([cipher.update(rawKey), cipher.final()]);
    const tag = cipher.getAuthTag();
    // Layout: iv(12) | tag(16) | ciphertext
    return Buffer.concat([iv, tag, ciphertext]).toString('base64');
  }

  private decrypt(encoded: string): Buffer {
    const masterKey = getMasterKey();
    const buf = Buffer.from(encoded, 'base64');
    const iv = buf.slice(0, 12);
    const tag = buf.slice(12, 28);
    const ciphertext = buf.slice(28);
    const decipher = crypto.createDecipheriv('aes-256-gcm', masterKey, iv);
    decipher.setAuthTag(tag);
    return Buffer.concat([decipher.update(ciphertext), decipher.final()]);
  }

  async storeKey(keyId: string, rawKey: Buffer, algorithm: string = 'aes-256-gcm'): Promise<void> {
    if (this.shutdownInProgress) throw new Error('Service shutting down');
    if (typeof keyId !== 'string' || keyId.length === 0 || keyId.length > 128) {
      throw new Error('Invalid keyId');
    }
    if (!ALLOWED_ALGORITHMS.includes(algorithm as AllowedAlgorithm)) {
      throw new Error('Invalid algorithm');
    }
    const encryptedKey = this.encrypt(rawKey);

    const record: KeyRecord = {
      keyId: String(keyId),
      encryptedKey,
      algorithm: String(algorithm),
      createdAt: new Date(),
      metadata: {}
    };

    const op = this.collection.insertOne(record as any);
    this.pendingOps.add(op);
    try { await op; } finally { this.pendingOps.delete(op); }
  }

  async retrieveKey(keyId: string, opts?: { algorithm?: string }): Promise<Buffer | null> {
    if (this.shutdownInProgress) throw new Error('Service shutting down');
    const filter = this.deriveQueryFilter(keyId, opts);
    const op = this.collection.findOne(filter);
    this.pendingOps.add(op);
    let record: KeyRecord | null;
    try { record = await op as KeyRecord | null; } finally { this.pendingOps.delete(op); }
    if (!record) return null;

    return this.decrypt(record.encryptedKey);
  }

  async rotateKey(keyId: string, newRawKey: Buffer): Promise<boolean> {
    if (this.shutdownInProgress) throw new Error('Service shutting down');
    const filter = this.deriveQueryFilter(keyId);
    const encryptedKey = this.encrypt(newRawKey);

    const op = this.collection.updateOne(filter, {
      $set: { encryptedKey, createdAt: new Date() }
    });
    this.pendingOps.add(op);
    try {
      const result = await op;
      return result.modifiedCount > 0;
    } finally { this.pendingOps.delete(op); }
  }

  async gracefulShutdown(): Promise<void> {
    this.shutdownInProgress = true;
    await Promise.allSettled([...this.pendingOps]);
  }
}

class KeyManagementServer {
  private server: http.Server;
  private store: CryptoKeyStore;
  private client: MongoClient;

  constructor(client: MongoClient, store: CryptoKeyStore) {
    this.client = client;
    this.store = store;
    this.server = http.createServer(this.handleRequest.bind(this));
  }

  private parseBody(req: http.IncomingMessage): Promise<any> {
    return new Promise((resolve, reject) => {
      let data = '';
      let size = 0;
      let settled = false;
      const done = (fn: () => void) => { if (!settled) { settled = true; fn(); } };

      const timeout = setTimeout(() => {
        done(() => reject(new Error('Request timed out')));
        req.destroy();
      }, 10000);

      req.on('data', chunk => {
        size += chunk.length;
        if (size > 10240) {
          clearTimeout(timeout);
          done(() => reject(new Error('Body too large')));
          req.destroy();
          return;
        }
        data += chunk;
      });
      req.on('end', () => {
        clearTimeout(timeout);
        try { done(() => resolve(JSON.parse(data))); }
        catch (e) { done(() => reject(new Error('Invalid JSON'))); }
      });
      req.on('error', (e) => {
        clearTimeout(timeout);
        done(() => reject(e));
      });
    });
  }

  private async handleRequest(req: http.IncomingMessage, res: http.ServerResponse) {
    try {
      if (req.method === 'POST' && req.url === '/keys/retrieve') {
        const body = await this.parseBody(req);
        const keyId = body.keyId;
        const opts = body.options;
        if (!keyId || typeof keyId !== 'string') {
          res.writeHead(400); res.end('{"error":"keyId required as string"}'); return;
        }
        if (opts && typeof opts === 'object') {
          if (opts.algorithm && typeof opts.algorithm !== 'string') {
            res.writeHead(400); res.end('{"error":"algorithm must be string"}'); return;
          }
        }
        const safeOpts = opts && typeof opts.algorithm === 'string' ? { algorithm: opts.algorithm } : undefined;
        const key = await this.store.retrieveKey(keyId, safeOpts);
        if (key) {
          res.writeHead(200, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ key: key.toString('hex') }));
        } else {
          res.writeHead(404); res.end('{"error":"not found"}');
        }
      } else if (req.method === 'POST' && req.url === '/keys/store') {
        const body = await this.parseBody(req);
        const { keyId, keyHex, algorithm } = body;
        if (!keyId || typeof keyId !== 'string' || !keyHex || typeof keyHex !== 'string') {
          res.writeHead(400); res.end('{"error":"keyId and keyHex required as strings"}'); return;
        }
        if (algorithm && typeof algorithm !== 'string') {
          res.writeHead(400); res.end('{"error":"algorithm must be string"}'); return;
        }
        await this.store.storeKey(keyId, Buffer.from(keyHex, 'hex'), algorithm);
        res.writeHead(201); res.end('{"status":"stored"}');
      } else if (req.method === 'POST' && req.url === '/keys/rotate') {
        const body = await this.parseBody(req);
        const { keyId, newKeyHex } = body;
        if (!keyId || typeof keyId !== 'string' || !newKeyHex || typeof newKeyHex !== 'string') {
          res.writeHead(400); res.end('{"error":"keyId and newKeyHex required as strings"}'); return;
        }
        const rotated = await this.store.rotateKey(keyId, Buffer.from(newKeyHex, 'hex'));
        res.writeHead(200); res.end(JSON.stringify({ rotated }));
      } else {
        res.writeHead(404); res.end('{"error":"not found"}');
      }
    } catch (err: any) {
      res.writeHead(500); res.end('{"error":"internal error"}');
    }
  }

  async start(port: number) {
    this.server.listen(port);
    process.on('SIGTERM', async () => {
      await this.store.gracefulShutdown();
      this.server.close();
      await this.client.close();
      process.exit(0);
    });
  }
}

async function main() {
  const client = new MongoClient(process.env.MONGO_URI || 'mongodb://localhost:27017');
  await client.connect();
  const db = client.db('keystore');
  const store = new CryptoKeyStore(db);
  const server = new KeyManagementServer(client, store);
  await server.start(parseInt(process.env.PORT || '3000'));
}

main().catch(console.error);
